import { Buffer } from 'node:buffer';

export type ParseResult =
  | { valid: true; token: string }
  | { valid: false; reason: 'missing' | 'malformed' | 'expired' };

function decodeBase64Url(input: string): string | null {
  const base64 = input.replace(/-/g, '+').replace(/_/g, '/');
  const padded = base64 + '='.repeat((4 - (base64.length % 4)) % 4);
  try {
    return Buffer.from(padded, 'base64').toString('utf8');
  } catch {
    return null;
  }
}

function parseJson(text: string): unknown {
  try {
    const value: unknown = JSON.parse(text);
    return value;
  } catch {
    return null;
  }
}

function getNumericExp(payload: unknown): number | null {
  if (typeof payload !== 'object' || payload === null) {
    return null;
  }
  if (!('exp' in payload)) {
    return null;
  }
  const exp: unknown = payload.exp;
  return typeof exp === 'number' ? exp : null;
}

export function parseAuthHeader(header: string, nowMs: number): ParseResult {
  const trimmed = header.trim();
  if (trimmed === '') {
    return { valid: false, reason: 'missing' };
  }

  const match = /^Bearer\s+(\S+)$/i.exec(trimmed);
  if (match === null) {
    return { valid: false, reason: 'malformed' };
  }

  const token = match[1];
  if (token === undefined) {
    return { valid: false, reason: 'malformed' };
  }

  const decoded = decodeBase64Url(token);
  if (decoded !== null) {
    const exp = getNumericExp(parseJson(decoded));
    if (exp !== null && exp * 1000 <= nowMs) {
      return { valid: false, reason: 'expired' };
    }
  }

  return { valid: true, token };
}

export function describeParseResult(result: ParseResult): string {
  if (result.valid) {
    return `token:${result.token}`;
  }
  switch (result.reason) {
    case 'missing':
      return 'missing';
    case 'malformed':
      return 'malformed';
    case 'expired':
      return 'expired';
    default: {
      const exhaustive: never = result;
      throw new Error(`Unhandled reason: ${String(exhaustive)}`);
    }
  }
}
