/** Value for an HTTP `Authorization` header, constructed via HTTP Basic auth. */
export type BasicAuthorization = `Basic ${string}`;

export function basicAuthorization(user: string, pw: string): BasicAuthorization {
  const token = Buffer.from(`${user}:${pw}`).toString("base64");
  return `Basic ${token}`;
}
